import React from 'react';
import Navigation from './Navigation';

interface LayoutProps {
  children: React.ReactNode;
}

const Layout: React.FC<LayoutProps> = ({ children }) => {
  return (
    <div className="min-h-screen bg-hitman-black flex flex-col md:flex-row">
      {/* Sidebar for Desktop */}
      <aside className="hidden md:flex flex-col w-64 bg-hitman-gray border-r border-gray-800 p-6 min-h-screen sticky top-0">
        <div className="mb-10">
          <h2 className="text-2xl font-black text-white italic tracking-tighter">
            HITMAN<span className="text-hitman-red font-normal">HOTLINE</span>
          </h2>
          <p className="text-[10px] text-gray-500 uppercase tracking-[0.2em]">Agency Management OS</p>
        </div>
        <Navigation />
      </aside>

      {/* Main Content */}
      <main className="flex-1 pb-20 md:pb-0 overflow-y-auto">
        {children}
      </main>

      {/* Mobile Navigation */}
      <div className="md:hidden">
        <Navigation />
      </div>
    </div>
  );
};

export default Layout;
